B.bBx=new A.a("\u041d\u0430 DEX \u043b\u044e\u0431\u043e\u0439 \u043c\u043e\u0436\u0435\u0442 \u0441\u043e\u0437\u0434\u0430\u0442\u044c \u0442\u043e\u043a\u0435\u043d. \u041f\u0440\u043e\u0432\u0435\u0440\u044f\u0439\u0442\u0435 \u0430\u0434\u0440\u0435\u0441 \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442\u0430, \u0447\u0442\u043e\u0431\u044b \u043d\u0435 \u043a\u0443\u043f\u0438\u0442\u044c \u043f\u043e\u0434\u0434\u0435\u043b\u043a\u0443.","\u041d\u0430 DEX \u0431\u0443\u0434\u044c-\u0445\u0442\u043e \u043c\u043e\u0436\u0435 \u0441\u0442\u0432\u043e\u0440\u0438\u0442\u0438 \u0442\u043e\u043a\u0435\u043d. \u041f\u0435\u0440\u0435\u0432\u0456\u0440\u044f\u0439\u0442\u0435 \u0430\u0434\u0440\u0435\u0441\u0443 \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442\u0443, \u0449\u043e\u0431 \u043d\u0435 \u043a\u0443\u043f\u0438\u0442\u0438 \u043f\u0456\u0434\u0440\u043e\u0431\u043a\u0443.","Anyone can create a token on a DEX. Verify the contract address to avoid fakes.")
B.cq8=new A.ad("dex",B.d4,B.bJQ,B.bHr,B.bBx)
