B.bMn=new A.a("\u0421\u043c\u043e\u0442\u0440\u0438\u0442\u0435 \u043d\u0430 \u0440\u0435\u0430\u043a\u0446\u0438\u044e: \u043e\u0442\u0431\u043e\u0439 \u2014 \u0443\u0440\u043e\u0432\u0435\u043d\u044c \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442; \u0431\u044b\u0441\u0442\u0440\u044b\u0439 \u043f\u0440\u043e\u0445\u043e\u0434 \u0441 \u043e\u0431\u044a\u0451\u043c\u043e\u043c \u2014 \u0434\u0430\u043b\u044c\u0448\u0435 \u043f\u0443\u0442\u044c \u0441\u0432\u043e\u0431\u043e\u0434\u0435\u043d.","\u0414\u0438\u0432\u0456\u0442\u044c\u0441\u044f \u043d\u0430 \u0440\u0435\u0430\u043a\u0446\u0456\u044e: \u0432\u0456\u0434\u0441\u043a\u043e\u043a \u2014 \u0440\u0456\u0432\u0435\u043d\u044c \u043f\u0440\u0430\u0446\u044e\u0454; \u0448\u0432\u0438\u0434\u043a\u0438\u0439 \u043f\u0440\u043e\u0445\u0456\u0434 \u0437 \u043e\u0431\u0441\u044f\u0433\u043e\u043c \u2014 \u0434\u0430\u043b\u0456 \u0448\u043b\u044f\u0445 \u0432\u0456\u043b\u044c\u043d\u0438\u0439.","Watch the reaction: a bounce means it holds; a fast pass on volume means the way is clear.")
B.c78=new A.a("\u0421\u0442\u0430\u0432\u0438\u0442\u044c \u0441\u0432\u043e\u0439 \u0442\u0435\u0439\u043a \u0440\u043e\u0432\u043d\u043e \u043d\u0430 \u043a\u0440\u0443\u0433\u043b\u043e\u0435 \u0447\u0438\u0441\u043b\u043e. \u041b\u0443\u0447\u0448\u0435 \u0447\u0443\u0442\u044c \u0440\u0430\u043d\u044c\u0448\u0435, \u0442\u0430\u043c \u043e\u0447\u0435\u0440\u0435\u0434\u044c \u043f\u0440\u043e\u0434\u0430\u0432\u0446\u043e\u0432.","\u0421\u0442\u0430\u0432\u0438\u0442\u0438 \u0441\u0432\u0456\u0439 \u0442\u0435\u0439\u043a \u0440\u0456\u0432\u043d\u043e \u043d\u0430 \u043a\u0440\u0443\u0433\u043b\u0435 \u0447\u0438\u0441\u043b\u043e. \u041a\u0440\u0430\u0449\u0435 \u0442\u0440\u043e\u0445\u0438 \u0440\u0430\u043d\u0456\u0448\u0435, \u0442\u0430\u043c \u0447\u0435\u0440\u0433\u0430 \u043f\u0440\u043e\u0434\u0430\u0432\u0446\u0456\u0432.","Placing your take-profit exactly on it. Set it a bit before \u2014 there's a queue of sellers.")
B.ayn=new A.bs(B.cR,B.d5,"round_number",B.bNy,B.bHv,B.bRg,B.bMn,B.c78)
B.bQe=new A.a("\u0412\u043e\u0441\u0445\u043e\u0434\u044f\u0449\u0430\u044f \u0442\u0440\u0435\u043d\u0434\u043e\u0432\u0430\u044f \u043b\u0438\u043d\u0438\u044f","\u0412\u0438\u0441\u0445\u0456\u0434\u043d\u0430 \u0442\u0440\u0435\u043d\u0434\u043e\u0432\u0430 \u043b\u0456\u043d\u0456\u044f","Rising trendline")
B.cim=new A.a("\u041b\u0438\u043d\u0438\u044f \u2197 \u0441\u043e\u0435\u0434\u0438\u043d\u044f\u0435\u0442 \u0434\u0432\u0430 \u043f\u043e\u0432\u044b\u0448\u0430\u044e\u0449\u0438\u0445\u0441\u044f \u043c\u0438\u043d\u0438\u043c\u0443\u043c\u0430. \u0421\u0435\u0439\u0447\u0430\u0441 \u043e\u043d\u0430 \u043f\u0440\u043e\u0445\u043e\u0434\u0438\u0442 \u043e\u043a\u043e\u043b\u043e {plevel}.","\u041b\u0456\u043d\u0456\u044f \u2197 \u0437\u02bc\u0454\u0434\u043d\u0443\u0454 \u0434\u0432\u0430 \u043c\u0456\u043d\u0456\u043c\u0443\u043c\u0438, \u0449\u043e \u043f\u0456\u0434\u0432\u0438\u0449\u0443\u044e\u0442\u044c\u0441\u044f. \u0417\u0430\u0440\u0430\u0437 \u0432\u043e\u043d\u0430 \u043f\u0440\u043e\u0445\u043e\u0434\u0438\u0442\u044c \u0431\u0456\u043b\u044f {plevel}.","The \u2197 line joins two rising lows. It is now around {plevel}.")
B.c17=new A.a("\u041f\u043e\u043a\u0430 \u0446\u0435\u043d\u0430 \u043d\u0430\u0434 \u043b\u0438\u043d\u0438\u0435\u0439, \u0432\u043e\u0441\u0445\u043e\u0434\u044f\u0449\u0438\u0439 \u0442\u0440\u0435\u043d\u0434 \u0436\u0438\u0432. \u041b\u0438\u043d\u0438\u044f \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u043a\u0430\u043a \xab\u043d\u0430\u043a\u043b\u043e\u043d\u043d\u0430\u044f \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0430\xbb.","\u041f\u043e\u043a\u0438 \u0446\u0456\u043d\u0430 \u043d\u0430\u0434 \u043b\u0456\u043d\u0456\u0454\u044e, \u0432\u0438\u0441\u0445\u0456\u0434\u043d\u0438\u0439 \u0442\u0440\u0435\u043d\u0434 \u0436\u0438\u0432\u0438\u0439. \u041b\u0456\u043d\u0456\u044f \u043f\u0440\u0430\u0446\u044e\u0454 \u044f\u043a \xab\u043f\u043e\u0445\u0438\u043b\u0430 \u043f\u0456\u0434\u0442\u0440\u0438\u043c\u043a\u0430\xbb.","While price stays above it the uptrend is alive. It acts as sloped support.")
B.ceT=new A.a("\u0422\u0440\u0435\u0442\u044c\u0435 \u043a\u0430\u0441\u0430\u043d\u0438\u0435 \u0441 \u043e\u0442\u0441\u043a\u043e\u043a\u043e\u043c \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442 \u043b\u0438\u043d\u0438\u044e. \u0427\u0435\u043c \u0431\u043e\u043b\u044c\u0448\u0435 \u043a\u0430\u0441\u0430\u043d\u0438\u0439, \u0442\u0435\u043c \u043e\u043d\u0430 \u0432\u0430\u0436\u043d\u0435\u0435.","\u0422\u0440\u0435\u0442\u0456\u0439 \u0434\u043e\u0442\u0438\u043a \u0456\u0437 \u0432\u0456\u0434\u0441\u043a\u043e\u043a\u043e\u043c \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0443\u0454 \u043b\u0456\u043d\u0456\u044e. \u0427\u0438\u043c \u0431\u0456\u043b\u044c\u0448\u0435 \u0434\u043e\u0442\u0438\u043a\u0456\u0432, \u0442\u0438\u043c \u0432\u043e\u043d\u0430 \u0432\u0430\u0436\u043b\u0438\u0432\u0456\u0448\u0430.","A third touch and bounce confirms the line. More touches, more importance.")
B.bU0=new A.a("\u041f\u043e\u0434\u0433\u043e\u043d\u044f\u0442\u044c \u043b\u0438\u043d\u0438\u044e \u043f\u043e\u0434 \u043d\u0443\u0436\u043d\u044b\u0439 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442. \u0415\u0451 \u043f\u0440\u043e\u0432\u043e\u0434\u044f\u0442 \u043f\u043e \u043c\u0438\u043d\u0438\u043c\u0443\u043c\u0430\u043c (\u0442\u0435\u043b\u0430\u043c \u0438\u043b\u0438 \u0442\u0435\u043d\u044f\u043c) \u043f\u043e\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u043d\u043e.","\u041f\u0456\u0434\u0433\u0430\u043d\u044f\u0442\u0438 \u043b\u0456\u043d\u0456\u044e \u043f\u0456\u0434 \u043f\u043e\u0442\u0440\u0456\u0431\u043d\u0438\u0439 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442. \u0407\u0457 \u043f\u0440\u043e\u0432\u043e\u0434\u044f\u0442\u044c \u043f\u043e \u043c\u0456\u043d\u0456\u043c\u0443\u043c\u0430\u0445 (\u0442\u0456\u043b\u0430\u0445 \u0430\u0431\u043e \u0442\u0456\u043d\u044f\u0445) \u043f\u043e\u0441\u043b\u0456\u0434\u043e\u0432\u043d\u043e.","Bending the line to fit your view. Draw it consistently through lows (bodies or wicks).")
